{"command":"python -c "
from tinydb import TinyDB, where
db = TinyDB()
db.insert_multiple([{'a': 1}, {'a': None}, {'a': 5}, {}])
for op in ['<', '<=', '>', '>=']:
    try:
        res = db.search(where('a') < 3) if op=='<' else db.search(where('a') <= 3) if op=='<=' else db.search(where('a') > 3) if op=='>' else db.search(where('a') >= 3)
        print(op, 'OK', [d['a'] for d in res if 'a' in d])
    except TypeError as e:
        print(op, 'CRASH:', e)
""}

{"command":"python -c "
from tinydb import TinyDB, where
from tinydb.storages import MemoryStorage
db = TinyDB(storage=MemoryStorage)
db.insert_multiple([{'a': 1}, {'a': None}, {'a': 5}, {}])
for op in ['<', '<=', '>', '>=']:
    try:
        if op=='<': res = db.search(where('a') < 3)
        elif op=='<=': res = db.search(where('a') <= 3)
        elif op=='>': res = db.search(where('a') > 3)
        else: res = db.search(where('a') >= 3)
        print(op, 'OK', [d['a'] for d in res if 'a' in d])
    except TypeError as e:
        print(op, 'CRASH:', e)
""}

